        worker.onmessage = (event: MessageEvent<{ id: number; arrows: Map<string, FloatingBoxArrow>; error?: string }>) => {
          if (this.worker !== worker || event.data.id !== this.inFlight?.id) return;
          if (event.data.error) { this.failWorker(); return; }
